-- Function: public.fn_assert_classroom_free
-- Backup generated on 2026-11-11 09:04:31

CREATE OR REPLACE FUNCTION public.fn_assert_classroom_free(p_tenant_id uuid, p_classroom_id uuid, p_date date, p_start time without time zone, p_end time without time zone, p_event_id uuid)  RETURNS void  LANGUAGE plpgsql AS $function$ DECLARE     c record; BEGIN     -- Serialize writers for the same classroom so concurrent saves cannot both succeed.     PERFORM pg_advisory_xact_lock(hashtextextended('classroom-slot:' || p_classroom_id::text, 0));      SELECT * INTO c FROM public.fn_find_classroom_conflicts(p_tenant_id, p_classroom_id, p_date, p_start, p_end, p_event_id) LIMIT 1;     IF FOUND THEN         RAISE EXCEPTION 'CLASSROOM_CONFLICT: Classroom is already booked % by "%"%. Cancel or move that activity first.',             CASE WHEN c.start_time IS NULL THEN 'all day'                  ELSE to_char(c.start_time, 'HH24:MI') || '–' || COALESCE(to_char(c.end_time, 'HH24:MI'), 'end of day') END,             c.title,             CASE WHEN c.organizer_name IS NULL THEN '' ELSE ' (' || c.organizer_name || ')' END             USING ERRCODE = 'EE409';     END IF; END; $function$ ;
